import { Component, OnDestroy, OnInit } from '@angular/core';
import { ActivatedRoute, Data, Params, Router } from '@angular/router';
import { TranslateService } from '@ngx-translate/core';
import { NgxSmartModalService } from 'ngx-smart-modal';
import { ToastrService } from 'ngx-toastr';
import { Subscription, combineLatest } from 'rxjs';
import {
  EnumDataSource,
  FieldDefinition,
  FixedDataSource,
  IFieldDataSource,
  IFieldOptions,
  MetaDataType,
} from 'shared-code-lib';
import { Log } from '../../blocks/core/log';
import {
  BrandOverride,
  IWorkflowStepPageLicenseCost,
  WorkflowStepCostType,
  WorkflowStepPageLicenseCost,
} from '../../blocks/models/workflow-step-page-license-cost';
import { ErrorsService } from '../../blocks/services/errors.service';
import { HydraApiService } from '../../blocks/services/hydra-api.service';
import { ApiResult, Control } from '../../blocks/services/models';
import { SpinnerStateService } from '../../blocks/services/spinner-state.service';
import { BrandInfo } from '../../blocks/models/marketing-blurb';

@Component({
  selector: 'app-admin-workflow-step-cost',
  templateUrl: './admin-workflow-step-cost.component.html',
  styleUrls: ['./admin-workflow-step-cost.component.scss'],
})
export class AdminWorkflowStepCostComponent implements OnInit, OnDestroy {
  rightControls: Array<Control> = [];

  routeParams: Params;
  routeData: Data;

  saveButton: Control;
  cancelButton: Control;

  stepDisplayNameField: FieldDefinition;
  costTypeField: FieldDefinition;
  costValueField: FieldDefinition;

  workflowStepPageLicenseCost: WorkflowStepPageLicenseCost;

  get baseCostType(): string {
    return this.workflowStepPageLicenseCost?.baseCostType.toString();
  }
  set baseCostType(val: string) {
    this.workflowStepPageLicenseCost.baseCostType = Number(val);
  }

  get baseCostValue(): string {
    return this.workflowStepPageLicenseCost?.baseCostValue.toString();
  }
  set baseCostValue(val: string) {
    this.workflowStepPageLicenseCost.baseCostValue = Number(val);
  }

  get newCostTypeString(): string {
    if (this.newCostType == null) return '';

    return this.newCostType.toString();
  }
  set newCostTypeString(val: string) {
    if (val == null) {
      this.newCostType = null;
      return;
    }

    this.newCostType = Number(val);
  }

  get newCostValueString(): string {
    return this.newCostValue?.toString() ?? '0';
  }
  set newCostValueString(val: string) {
    if (!val) {
      this.newCostValue = 0;
      return;
    }

    this.newCostValue = Number(val);
  }

  newCostBrand: string;
  newCostType: WorkflowStepCostType;
  newCostValue: number;
  brandsDataSource: FixedDataSource = new FixedDataSource();
  costTypesDataSource: FixedDataSource = new FixedDataSource();
  allBrands: Array<BrandInfo> = [];
  MetaDataType = MetaDataType;

  subscriptions = new Subscription();

  constructor(
    private translateService: TranslateService,
    private router: Router,
    private route: ActivatedRoute,
    private hydraApi: HydraApiService,
    private toastr: ToastrService,
    private errorsService: ErrorsService,
    private spinner: SpinnerStateService,
    public ngxSmartModalService: NgxSmartModalService
  ) {}

  ngOnInit() {
    this.createButtons();
    this.createFields();
    this.loadBrands();
    this.costTypesDataSource = new EnumDataSource(
      WorkflowStepCostType,
      'WorkflowStepCostTypeEnum',
      this.translateService
    );

    this.subscriptions.add(
      combineLatest([this.route.params, this.route.data]).subscribe(([params, data]) => {
        this.routeParams = params;
        this.routeData = data;

        if (this.routeData.type == 'create') {
          this.workflowStepPageLicenseCost = new WorkflowStepPageLicenseCost({
            workflowStepClassName: '',
            workflowStepDisplayName: '',
            baseCostType: WorkflowStepCostType.Constant,
            baseCostValue: 0,
            dateCreatedUTC: new Date(new Date().toUTCString()),
            dateModifiedUTC: new Date(new Date().toUTCString()),
          } as IWorkflowStepPageLicenseCost);
        } else {
          this.loadItems();
        }
      })
    );
  }

  private createButtons = () => {
    this.saveButton = new Control(this.onSave, 'Save', 'btn btn-primary btn-minwidth', '', '', 'btn', false);
    this.cancelButton = new Control(this.onCancel, 'Cancel', 'btn btn-light btn-minwidth', '', '', 'btn', false);
    this.rightControls.push(this.saveButton);
    this.rightControls.push(this.cancelButton);

    this.saveButton.setTranslation(this.translateService.instant('Common.Save'));
    this.cancelButton.setTranslation(this.translateService.instant('Common.Cancel'));
  };

  createFields = (): void => {
    this.stepDisplayNameField = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translateService.instant('admin-workflow-step-cost.step-name'),
      placeholder: this.translateService.instant('admin-workflow-step-cost.step-name'),
      required: true,
    });

    const options: IFieldOptions[] = [
      { name: this.translateService.instant('admin-workflow-step-cost.constant'), value: '0' },
      { name: this.translateService.instant('admin-workflow-step-cost.multiplier'), value: '1' },
    ];

    this.costTypeField = new FieldDefinition({
      type: MetaDataType.List,
      label: this.translateService.instant('admin-workflow-step-cost.type'),
      placeholder: this.translateService.instant('admin-workflow-step-cost.type'),
      datasource: new FixedDataSource(options),
      required: true,
    });

    this.costValueField = new FieldDefinition({
      type: MetaDataType.Decimal,
      label: this.translateService.instant('admin-workflow-step-cost.value'),
      placeholder: this.translateService.instant('admin-workflow-step-cost.value'),
      required: true,
    });
  };

  loadItems = (): void => {
    if (this.routeData.type !== 'properties') return;

    this.spinner.show(this.translateService.instant('admin-workflow-step-cost.loading-item'), document.body);
    this.hydraApi.getWorkflowStepCost(
      this.routeParams.workflowcostid,
      this.workflowStepCostLoaded,
      this.loadingWorkflowStepCostFailed
    );
  };

  workflowStepCostLoaded = (loadedItem: any): void => {
    this.workflowStepPageLicenseCost = loadedItem;
    this.spinner.hide(this.translateService.instant('admin-workflow-step-cost.loading-item'));
  };

  loadingWorkflowStepCostFailed = (error: any): void => {
    this.toastr.error(this.translateService.instant('admin-workflow-step-cost.loading-item-failed'));
    Log.error('admin-workflow-step-cost.loading-item-failed', error);
    this.spinner.hide(this.translateService.instant('admin-workflow-step-cost.loading-item'));
  };

  loadBrands() {
    this.spinner.show(this.translateService.instant('admin-marketing-blurb.loading-brands'), document.documentElement);
    this.hydraApi.getBrands(this.brandsLoaded, this.brandsLoadfailed);
  }

  brandsLoaded = (apiResult: ApiResult) => {
    if (!apiResult.success) {
      this.brandsLoadfailed(apiResult.errors);
      return;
    }

    this.allBrands = (apiResult.object as Array<any>).map((item) => new BrandInfo(item));
    this.createBrandsList();
    this.spinner.hide(this.translateService.instant('admin-marketing-blurb.loading-brands'));
  };

  brandsLoadfailed = (err): void => {
    this.toastr.error(this.translateService.instant('admin-workflow-step-cost.brands-load-failed'));
    Log.error('AdminWorkflowStepCostComponent.brandsLoadfailed', err);
    this.spinner.hide(this.translateService.instant('admin-marketing-blurb.loading-brands'));
  };

  CreateField = (
    label: string,
    required: boolean = false,
    type = MetaDataType.Text,
    datasource: IFieldDataSource = null
  ): FieldDefinition => {
    return new FieldDefinition({
      type: type,
      label: label ? this.translateService.instant(label) : '',
      placeholder: label ? this.translateService.instant(label) : '',
      required: required,
      datasource: datasource,
    });
  };

  onAddCost = (): void => {
    if (!this.newCostBrand) return;

    const brandParts = this.newCostBrand.split(':');
    const newBrandOverride: BrandOverride = new BrandOverride({
      brandID: brandParts[0],
      dealerID: brandParts.length > 1 ? brandParts[1] : null,
      baseCostType: this.newCostType,
      baseCostValue: this.newCostValue,
    });

    this.workflowStepPageLicenseCost.brandOverrides.push(newBrandOverride);

    this.resetFields();
  };

  resetFields = (): void => {
    this.createBrandsList();

    this.newCostBrand = '';
    this.newCostValueString = '';
    this.newCostTypeString = null;

    this.onNewCostValueChanged();
  };

  onDeleteCost = (index: number): void => {
    if (!this.workflowStepPageLicenseCost?.brandOverrides) return;

    this.workflowStepPageLicenseCost.brandOverrides.splice(index, 1);
    this.createBrandsList();
  };

  onCostTypeChanged = (val, index): void => {
    if (!this.workflowStepPageLicenseCost?.brandOverrides) return;
    if (index >= this.workflowStepPageLicenseCost.brandOverrides.length) return;

    this.workflowStepPageLicenseCost.brandOverrides[index].baseCostType = Number(val);
  };

  onCostValueChanged = (val, index): void => {
    if (!this.workflowStepPageLicenseCost?.brandOverrides) return;
    if (index >= this.workflowStepPageLicenseCost.brandOverrides.length) return;

    this.workflowStepPageLicenseCost.brandOverrides[index].baseCostValue = Number(val);
  };

  getBrandName = (brandId: string, dealerId: string): string => {
    return this.allBrands.find((x) => x.brandId === brandId && x.dealerId === dealerId)?.name;
  };

  createBrandsList = (): void => {
    const options: IFieldOptions[] = [];
    this.allBrands.forEach((brand) => {
      if (
        this.workflowStepPageLicenseCost.brandOverrides.findIndex(
          (x) => x.brandID === brand.brandId && x.dealerID === brand.dealerId
        ) !== -1
      )
        return;

      const value = brand.dealerId ? `${brand.brandId}:${brand.dealerId}` : brand.brandId;
      options.push({ name: brand.name, value: value });
    });

    this.brandsDataSource.updateOptions(options);
  };

  onNewCostValueChanged = () => {
    if (!this.saveButton) return;

    this.saveButton.isDisabled = !!this.newCostBrand || this.newCostType !== null || !!this.newCostValue;
  };

  onSave = () => {
    if (this.workflowStepPageLicenseCost.id) {
      this.hydraApi.updateWorkflowStepCost(this.workflowStepPageLicenseCost, this.savedSuccessfully, this.saveFailed);
    } else {
      this.hydraApi.createWorkflowStepCost(this.workflowStepPageLicenseCost, this.savedSuccessfully, this.saveFailed);
    }

    this.spinner.showSavingSpinner();
  };

  savedSuccessfully = (result: ApiResult) => {
    if (result.success) {
      this.toastr.success(this.translateService.instant('admin-workflow-step-cost.saved'));
      this.returnToGrid();
    } else {
      this.errorsService.showErrorsModal(result.errors, 'admin-workflow-step-cost.validation-errors');
    }

    this.spinner.hide();
  };

  saveFailed = (error: any) => {
    this.toastr.error(this.translateService.instant('admin-workflow-step-cost.save-failed'));
    Log.error('admin-workflow-step-cost.save-failed', error);
    this.spinner.hide();
  };

  onCancel = () => {
    this.returnToGrid();
  };

  returnToGrid = () => {
    this.router.navigateByUrl(
      'settings/BambaAdministratorApplication/BambaAdministratorApplication-Upland.Bamba.Application.Settings.WorkflowStepPageLicenseCosts'
    );
  };

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }
}
